/**
 * Organization Settings Types — Sawaa Dashboard
 *
 * Response shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. Request payloads stay local and are marked as such.
 */

import type { components } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

type OrganizationSettingsWire = Schemas["OrganizationSettingsResponseDto"]

/**
 * Dashboard-facing organization settings.
 *
 * `vatRate` is a Prisma `Decimal` on the row, so it arrives as a decimal
 * string, never a number. The settings forms divide it as a fraction
 * (`toPercent` uses `Number(rate)`) and the money helpers accept
 * `number | null | undefined`, so this alias keeps the wire string and lets
 * every reader coerce. Do not narrow it to `number` — the wire would not match.
 */
export type OrganizationSettings = OrganizationSettingsWire

/**
 * The PATCH body.
 *
 * `UpsertOrgSettingsDto` accepts a subset of the row's fields, all optional,
 * and several of them accept `null` to clear the column even though the DTO
 * omits that from OpenAPI — so the payload stays local rather than derived.
 * `vatRate` is the one field whose write type genuinely differs from the read
 * type: the row stores a Prisma `Decimal` (a string on the wire) and the DTO
 * validates a `number` fraction.
 */
export type UpdateOrganizationSettingsPayload = Partial<
  Omit<OrganizationSettings, "id" | "createdAt" | "updatedAt" | "vatRate">
> & { vatRate?: number }
